const T = $('ENTRADA (Execute Workflow Trigger)').item.json;
const caja = (T.caja || 'tiquipaya').toString().trim().toLowerCase();

if (caja !== 'tiquipaya' && caja !== 'america') {
  throw new Error('CAJA_DESCONOCIDA: "' + caja + '". Cajas validas: america, tiquipaya.');
}

// Defaults TIQUIPAYA: EXACTAMENTE los folder IDs historicos de este
// workflow (FASE 11A.1/11A.2). Solo se usan si DRIVE_*_TIQ no esta
// definida -- asi TIQUIPAYA sigue funcionando igual que siempre aunque
// no se despliegue ninguna variable de entorno nueva.
const DEFAULTS_TIQ = {
  entrada: '1ntneoE3MI-25FyPXUymXEvIJmnaZWyJ1',
  sap: '1mid4gUHnCmZbISlsAYMwWta3RudTSE13',
  resultado: '16Z7Uhf-NgiZ6YuqWLnReaIozRIiOg5HO',
  procesados: '1BkNC6lnonMM7YeWDKck-TM8WTyY2BJJP',
  marker: '1i8wXRM-2yiH5N3SPOEd4eEqZnizCeCGu',
};

// AMERICA: SIN defaults a proposito -- no existen carpetas reales todavia
// y NUNCA se reutilizan las de TIQUIPAYA. Hasta que DRIVE_*_AME se
// configure, cualquier intento de publicar como america falla cerrado.
const PREFIJOS = {
  tiquipaya: ['SAP_TIQ_', 'SAP_GLOBAL_TIQ_', 'RESULTADO_TIQ_'],
  america: ['SAP_AME_', 'SAP_GLOBAL_AME_', 'RESULTADO_AME_'],
};

function validarPrefijo(nombreArchivo) {
  if (!nombreArchivo) return;
  const propios = PREFIJOS[caja];
  if (propios.some(function (p) { return nombreArchivo.startsWith(p); })) return;
  const otras = Object.keys(PREFIJOS).filter(function (c) { return c !== caja; });
  for (const otra of otras) {
    if (PREFIJOS[otra].some(function (p) { return nombreArchivo.startsWith(p); })) {
      throw new Error('PREFIJO_CAJA_NO_COINCIDE: "' + nombreArchivo + '" tiene prefijo de ' + otra.toUpperCase() + ' pero se esta publicando como ' + caja.toUpperCase() + '.');
    }
  }
}

validarPrefijo((T.ruta_sap_publicado || '').split('/').pop());
validarPrefijo((T.ruta_resultado_publicado || '').split('/').pop());

function resolverDestino(clave) {
  const envVar = 'DRIVE_' + clave.toUpperCase() + '_' + (caja === 'america' ? 'AME' : 'TIQ');
  const valor = $env[envVar];
  if (valor) return valor;
  if (caja === 'tiquipaya') return DEFAULTS_TIQ[clave];
  throw new Error('DRIVE_AME_PENDIENTE: falta configurar ' + envVar + ' (carpeta "' + clave + '" de CAJA AMERICA todavia no existe en Drive).');
}

return [{ json: {
  caja: caja,
  folder_entrada: resolverDestino('entrada'),
  folder_sap: resolverDestino('sap'),
  folder_resultado: resolverDestino('resultado'),
  folder_procesados: resolverDestino('procesados'),
  folder_marker: resolverDestino('marker'),
} }];

const t = $('ENTRADA (Execute Workflow Trigger)').first().json;
const caja = $('RESOLVER - Destinos Drive por caja').first().json.caja;
const marker = $('BUSCAR - Marker existente (preflight)').all().map(function(it){return it.json;}).filter(function(j){return j && j.id;});
const cierre = $('BUSCAR - Cierre exacto en ENTRADA (preflight)').all().map(function(it){return it.json;}).filter(function(j){return j && j.name === t.archivo_esperado && j.id;});
const sap = $('BUSCAR - SAP oficial existente (preflight)').all().map(function(it){return it.json;}).filter(function(j){return j && j.name === t.ruta_sap_publicado.split('/').pop() && j.id;});
const resultado = $('BUSCAR - Resultado oficial existente (preflight)').all().map(function(it){return it.json;}).filter(function(j){return j && j.name === t.ruta_resultado_publicado.split('/').pop() && j.id;});

const markerYaExiste = marker.length > 0;
const cierreAmbiguo = cierre.length > 1;
const cierreResuelto = cierre.length === 1;
const cierreFileIdCoincide = cierreResuelto && (!t.drive_file_id || cierre[0].id === t.drive_file_id);
const sapDuplicado = sap.length > 1;
const sapYaExiste = sap.length === 1;
const resultadoDuplicado = resultado.length > 1;
const resultadoYaExiste = resultado.length === 1;

const bloqueadores = [];
if (markerYaExiste) bloqueadores.push('MARKER_YA_EXISTE');
if (cierreAmbiguo) bloqueadores.push('CIERRE_AMBIGUO_EN_ENTRADA');
if (!cierreResuelto && !markerYaExiste) bloqueadores.push('CIERRE_NO_RESUELTO_EN_ENTRADA');
if (cierreResuelto && !cierreFileIdCoincide) bloqueadores.push('FILEID_INGESTA_NO_COINCIDE');
if (sapDuplicado) bloqueadores.push('SAP_DUPLICADO');
if (resultadoDuplicado) bloqueadores.push('RESULTADO_DUPLICADO');

return [{ json: {
  fecha: t.fecha, archivo_esperado: t.archivo_esperado, sha256: t.sha256, caja: caja,
  carpetas_accesibles: true,
  marker_ya_existe: markerYaExiste,
  cierre_resuelto: cierreResuelto, cierre_ambiguo: cierreAmbiguo, cierre_fileid_coincide: cierreFileIdCoincide,
  sap_ya_existe: sapYaExiste, sap_duplicado: sapDuplicado,
  resultado_ya_existe: resultadoYaExiste, resultado_duplicado: resultadoDuplicado,
  bloqueadores: bloqueadores,
  apto_para_publicar: bloqueadores.length === 0,
  mensaje: bloqueadores.length === 0
    ? (markerYaExiste ? 'YA_PUBLICADO (idempotente): nada que bloquee, pero tampoco hay nada nuevo que publicar.' : 'Apto para publicar: carpetas accesibles, cierre resuelto, sin duplicados.')
    : 'Bloqueado: ' + bloqueadores.join(', '),
} }];
